import{_ as n,C as o,o as r,c as l,a3 as i,E as h,w as c,j as e,a as t}from"./chunks/framework.CxHH7c4T.js";const y=JSON.parse('{"title":"Use the S32 with AI","description":"","frontmatter":{},"headers":[],"relativePath":"ai/index.md","filePath":"ai/index.md"}'),p={name:"ai/index.md"};function d(u,a,f,m,g,k){const s=o("ManualRelated");return r(),l("div",null,[a[1]||(a[1]=i('<h1 id="use-the-s32-with-ai" tabindex="-1">Use the S32 with AI <a class="header-anchor" href="#use-the-s32-with-ai" aria-label="Permalink to &quot;Use the S32 with AI&quot;">​</a></h1><p>An AI agent can build racks, map knobs and set up LFOs on your S32 while you play. You say what you want in plain words. The agent runs the commands, shows you what it will change, and checks the result.</p><p>It needs an agent that can run commands on your computer. A chat-only app can read these pages, but it cannot reach your S32.</p><h2 id="in-three-steps" tabindex="-1">In three steps <a class="header-anchor" href="#in-three-steps" aria-label="Permalink to &quot;In three steps&quot;">​</a></h2><ol><li><strong><a href="./setup">Set up your agent</a>.</strong> Paste one block into your agent. It installs the s32 CLI, checks the link to your S32 and saves the s32-cli skill with the rules it follows.</li><li><strong><a href="./prompts">Try a prompt</a>.</strong> Start with a quick starter: ask what is on your S32, arpeggiate your keyboard, or put a filter cutoff on a knob.</li><li><strong><a href="./safe-changes">Change safely</a>.</strong> The agent reads first, previews, asks you, changes, then checks. A few commands that change a lot at once always ask for your yes.</li></ol><p>Close the <a href="https://editor.shik.tech" target="_blank" rel="noreferrer">web editor</a> while an agent works: the S32 talks to one app at a time.</p><p>Agents that read this manual find an index of its pages in <a href="./for-agents">For agents</a>. Prefer to type the commands yourself? See the <a href="./../developers/">s32 CLI</a>.</p>',7)),h(s,null,{default:c(()=>[...a[0]||(a[0]=[e("ul",null,[e("li",null,[e("a",{href:"./setup"},"Set up your agent"),t(" — Paste one block; the agent installs, checks and saves the rules")]),e("li",null,[e("a",{href:"./prompts"},"Prompts and examples"),t(" — Quick starters and prompts for racks, modulation and knob mappings, with checked commands")]),e("li",null,[e("a",{href:"./safe-changes"},"Change safely"),t(" — Read, preview, ask, change, check")]),e("li",null,[e("a",{href:"./for-agents"},"For agents"),t(" — What agents read: llms.txt, Markdown copies, finding commands")])],-1)])]),_:1})])}const _=n(p,[["render",d]]);export{y as __pageData,_ as default};
